    <tr><td>近身诡刃刺杀</td><td class="lvl">A</td><td>看似困倦无力的表象下，是极端精准与致命的爆发力。她藏于宽大袖袍中的短刀“绯刺”，配合狐属型锚点的灵动身法，可瞬息间切入敌方防御薄弱点。</td></tr>

