        id: 'P-400',



        title: '威胁评估档案 · 三更堂',



        category: '威胁评估档案',



        subCategory: '危险组织',



        tags: ['三更堂', '鬼市', '地下交易', '收容物交易', '金堂', '玉堂', '猎堂小组'],



        summary: '华墟境内历史最悠久、规模最大的地下收容物交易网络，存在时间比总局更古老，根基深植于民间。',



        content: `



<div class="section-title">🏮 补充档案：三更堂</div>



<p><strong>组织全称</strong>：三更堂（民间亦称「鬼市堂」「老堂口」）<br><strong>组织定位</strong>：华墟境内历史最悠久、规模最大的<strong>地下收容物交易网络</strong>。其存在时间比总局更古老，根基深植于民间。<br><strong>威胁评估</strong>：丙·未（组织性威胁高，个体危害随交易物等级浮动）</p>



<div class="section-title">一、历史沿革</div>



<div class="section-title">玄古纪至周宗时期（萌芽）</div>



<p>三更堂的雏形可追溯至玄古纪末期的「墟市」——当时已有先民在墟域残留地附近自发交换「那些从瘴境里带出来的东西」。周宗时期，这类交易被官方定性为「妖市」，屡禁不止，转入地下，形成固定集会，多在<strong>月晦之夜、城郊废祠</strong>举行。</p>



<div class="section-title">汉昌至南北衡时期（成型）</div>



<p>汉昌年间，有术士家族「殷氏」将各处零散鬼市整合，建立了最早的交易规则与信用体系，被后世尊为三更堂的奠基者。南北衡时期玄学大兴，大量士族参与收藏与交易，三更堂从草根江湖跻身士大夫阶层的隐秘雅好。</p>



<div class="section-title">隋鸿至宋文时期（鼎盛）</div>



<p>隋鸿时期，三更堂在各大州府建立了<strong>暗桩网络</strong>，以当铺、药铺、古玩店为掩护。宋文时期达到顶峰，甚至有官员暗中参与。据传，宋文宗年间一场宫廷火灾中失踪的「玄铁九鼎」（传说为一件丁阶收容物），正是通过三更堂流向民间，至今下落不明。</p>



<div class="section-title">元朔至明曜时期（分裂与重构）</div>



<p>元朔时期，三更堂因内部权力斗争分裂为南北两派。北派「金堂」偏重交易高战力收容物，多与军方残部勾结；南派「玉堂」偏重收容物的研究、仿制与信息贩卖。明曜中期，南派玉堂被官府清剿几近覆灭，残部被北派金堂收编。现三更堂主体为金堂一脉。</p>



<div class="section-title">清定至华墟共和国时期（当代形态）</div>



<p>清定时期，三更堂与官方的「钦天监 · 异象司」（总局前身）形成了<strong>微妙的共存关系</strong>——官方偶尔通过三更堂获取不便公开出手的收容物，三更堂则提供情报作为交换。华墟共和国成立、总局设立后，这种默契被打破，总局对三更堂进行了<strong>持续数十年的清剿</strong>，但始终无法彻底根除。当代三更堂高度分散，以<strong>小型独立堂口</strong>的形式存在于各省市，彼此之间保持松散的情报交流，但无统一的中央指挥。</p>



<div class="section-title">二、组织架构</div>



<p>三更堂当代已无统一架构，但各堂口普遍遵循以下职位体系：</p>



<ul class="detail-list">

    <li><strong>堂主</strong>（1人）：掌控堂口全部事务，多为资深觉醒者或世代经营此道的家族话事人。</li>

    <li><strong>暗桩</strong>（若干）：分布于各行业，负责收集情报、物色买主、寻找货源。常用掩护身份包括：典当行朝奉、殡葬铺老板、古玩店东家、茶馆/酒肆老板、货车司机等。</li>

    <li><strong>走水</strong>（数人）：负责收容物的运输与交接，通常由低阶觉醒者担任，偶有亡命徒。高风险职业，运输途中被总局查获或自身被收容物反噬的事件频发。</li>

    <li><strong>掌眼</strong>（1-2人）：负责鉴定收容物的真伪、风险等级与大致规则。掌眼通常是三更堂中最具学识的人物，部分掌眼本身就是玄理科研院的前研究人员或民间术士。</li>

    <li><strong>护法</strong>（数人）：负责堂口的安全保卫，多为战斗型觉醒者，武力值普遍高于堂口其他成员。</li>

</ul>



<div class="section-title">三、交易规则</div>



<p>三更堂的交易遵循一套严格的<strong>不成文规矩</strong>：</p>



<ol class="detail-list">

    <li><strong>不问来路</strong>：卖方不需说明收容物来源，买方不需说明用途。</li>

    <li><strong>自担风险</strong>：交易完成后，因使用不当造成的后果与堂口无关。</li>

    <li><strong>三不碰</strong>：不碰丁阶及以上收容物（堂口无能力确保规则完整）、不碰总局明确标记为「镇国之器」的收容物（怕惹来灭顶之灾）、不碰活物。</li>

    <li><strong>等价交换</strong>：除金钱外，三更堂也接受「情报」「人情」或「一件尚未鉴定的器物」作为交换媒介。</li>

    <li><strong>暗号准入</strong>：新客户需通过老客户引荐，并在特定场合说出当季暗号。</li>

</ol>



<div class="section-title">四、与总局的关系</div>



<p><strong>动态对抗关系</strong>。总局外勤行动司设有「猎堂小组」，专门追查三更堂堂口。但三更堂的堂口极其隐蔽，且与地方社会生态高度融合，清剿行动往往成效有限。更令总局忌惮的是：部分三更堂堂口与<strong>浊化者</strong>存在情报往来，甚至曾有堂口向浊化者出售过可用于「加速浊化」的收容物。</p>



        `



