        name: '赤湮',



        level: '己阶',



        type: '攻击型（献祭 / 返还）',



        holder: '暮祁（在逃）',



        origin: '原沧溟府库藏，暮祁叛逃时窃取。',



        appearance: '项目外观为一柄刃长约110cm的漆黑唐刀，刃纹在微观视野下呈干涸血脉状。该项目的核心机制为“献祭-返还”循环：每挥出一刀，使用者必须支付一次代价（体力、精力或特定的精神状态），而随后的一次或数次攻击，其威力将呈指数级提升。',



        mechanism: '“赤湮”的代价机制可量化为使用者“存在感”的持续稀释。存在感在此处被定义为：个体在他人知觉中的可识别度与在现实中的锚定强度。\n1. 常规使用（单次挥斩）：使用后10至30分钟内，使用者的存在感将降低至常人基准值以下。此状态表现为：周围人员在非直接注视时，对使用者的即时记忆留存率下降约40%。此效果可逆，休息后恢复。\n2. 连续使用（3次以上）：效果将产生质变。使用者会主观体验到一种“自身重量感”的丧失，需要通过外部感官反馈（如握刀、触碰实体物件）来证实自身的存在。此效应具有累积性，需较长时间方可消退。\n3. 高强度使用（五斩以上或全力一击）：在极少数情况下，使用者会在短时间内从周围人员的知觉场中“消失”数秒至数分钟。此期间，外界无法通过任何感官手段锁定其位置。此状态属于高危事件，且每次发生，都会在更低的使用次数阈值上增加未来再次触发的概率。\n4. 预估终局：根据“赤湮”的长期适配模型推测，若“存在感”稀释达到临界点（约75%-80%），使用者将彻底从现实知觉中剥离，成为一把“不被任何人记得的刀”。根据总局档案记录，该项行为尚未发生，暮祁当前的估算稀释率约为28%-31%。',



        restrictions: '使用权限严格管控：暮祁仅在确认非用不可时调用该项目。日常战斗任务中，他备有一把代号“巡刃”的常规制式佩刀，仅在遭遇己阶及以上威胁或需破除物理结界时，方解锁“赤湮”的使用权限。此举有效控制了“存在感”的稀释速率，使当前状态维持在可长期管理的水平。',



        events: '① 暮祁叛逃时自沧溟府库藏窃取。\n② 配合暮祁的刀术使用，组合威胁度可达丁阶门槛。',



        status: '在逃 · 随暮祁',



        notes: '暮祁是已知唯一与该收容物达成长期平衡的使用者。他使用该项目的时机被严格管控，其“存在感”稀释率约为28%-31%，尚未达到临界点。其与绯燎的互动模式，也被观测到具有锚定其存在感的客观辅助效果。'



